/*
 * Concept 08: Floating Solar Field - Water and Energy
 * Duration: 25 seconds
 * Resolution: 3840 x 2160
 * Frame rate: 60 fps
 * One continuous scene; deterministic seamless loop; time is in seconds.
 * Canvas 2D only. No assets, imports, DOM, glow, bloom, or blur.
 * Export target: 100 Mbps (100000000 bits per second).
 * The host encoder must enforce the bitrate; Canvas itself draws frames only.
 *
 * Revision notes (motion + geometry pass):
 *  - Water, platforms, walkway, gangway and shore share ONE oblique projection,
 *    so every edge, face and label follows the same axes.
 *  - Layout is symmetric about the walkway axis; margins and gaps are explicit constants.
 *  - Platforms heave as one rigid body (pure vertical translation, no scaling);
 *    the gangway rotates rigidly about its fixed hinge on the quay.
 *  - Light sweep is one global, eased band instead of per-module offsets.
 *  - Energy packets run at one constant speed with even spacing and merge on the trunk.
 *  - Every periodic term uses a whole number of cycles per 25 s, so the loop is seamless.
 */
'use strict';

const meta = Object.freeze({
  id: 'floating_solar_field',
  title: 'Floating Solar Field - Water and Energy',
  width: 3840,
  height: 2160,
  fps: 60,
  duration: 25,
  sceneCount: 1,
  targetVideoBitrate: 100000000,
  background: '#0a0d14'
});

const SolarKit = (() => {
  const TAU = Math.PI * 2;
  const FONT = 'Arial, "DejaVu Sans", Helvetica, sans-serif';
  const fract = n => n - Math.floor(n);
  const clamp = (n, a = 0, b = 1) => Math.max(a, Math.min(b, n));
  const lerp = (a, b, n) => a + (b - a) * n;
  function smooth(a, b, n) {
    const u = clamp((n - a) / (b - a));
    return u * u * (3 - 2 * u);
  }
  const easeInOutSine = n => 0.5 - 0.5 * Math.cos(Math.PI * clamp(n));

  const rgbCache = new Map();
  function rgbOf(hex) {
    let c = rgbCache.get(hex);
    if (!c) { c = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16)); rgbCache.set(hex, c); }
    return c;
  }
  function mix(a, b, n) {
    const x = rgbOf(a), y = rgbOf(b);
    return 'rgb(' + Math.round(lerp(x[0], y[0], n)) + ',' + Math.round(lerp(x[1], y[1], n)) + ',' +
      Math.round(lerp(x[2], y[2], n)) + ')';
  }
  function rgba(hex, alpha) {
    const c = rgbOf(hex);
    return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + alpha + ')';
  }

  function polygon(ctx, points, fill, stroke, lineWidth = 1) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth; ctx.stroke(); }
  }
  function roundedPath(ctx, x, y, w, h, radius = 10) {
    const r = Math.min(radius, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function box(ctx, x, y, w, h, fill, stroke, radius = 10, lineWidth = 1) {
    roundedPath(ctx, x, y, w, h, radius);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth; ctx.stroke(); }
  }
  function line(ctx, points, color, width = 1) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.stroke();
  }
  function circle(ctx, x, y, r, fill, stroke, lineWidth = 1) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth; ctx.stroke(); }
  }
  function text(ctx, value, x, y, size, color, weight = 400, align = 'left', maxWidth = Infinity) {
    ctx.save();
    let fitted = size;
    ctx.font = weight + ' ' + fitted + 'px ' + FONT;
    const measured = ctx.measureText(value).width;
    if (measured > maxWidth) {
      fitted *= maxWidth / measured;
      ctx.font = weight + ' ' + fitted + 'px ' + FONT;
    }
    ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color; ctx.fillText(value, x, y);
    ctx.restore();
  }

  const letterLayouts = new Map();
  function layoutOf(ctx, value, size, tracking, maxWidth) {
    const key = value + '|' + size + '|' + tracking + '|' + maxWidth;
    let layout = letterLayouts.get(key);
    if (!layout) {
      ctx.save();
      ctx.font = '600 ' + size + 'px ' + FONT;
      const letters = Array.from(value);
      const widths = letters.map(c => ctx.measureText(c).width);
      const total = widths.reduce((a, b) => a + b, 0) + tracking * Math.max(0, letters.length - 1);
      const scale = Math.min(1, maxWidth / Math.max(total, 0.01));
      ctx.restore();
      layout = {letters, widths, scale, width: total * scale};
      letterLayouts.set(key, layout);
    }
    return layout;
  }
  function spacedWidth(ctx, value, size, tracking, maxWidth = Infinity) {
    return layoutOf(ctx, value, size, tracking, maxWidth).width;
  }
  // Letter-spaced text. Returns the drawn width so callers can lay items out by measurement.
  function spaced(ctx, value, x, y, size, tracking, color, maxWidth = Infinity, align = 'left') {
    const {letters, widths, scale, width} = layoutOf(ctx, value, size, tracking, maxWidth);
    ctx.save();
    ctx.font = '600 ' + size * scale + 'px ' + FONT;
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = color;
    let cursor = align === 'right' ? x - width : align === 'center' ? x - width * 0.5 : x;
    letters.forEach((letter, i) => {
      ctx.fillText(letter, cursor, y);
      cursor += (widths[i] + tracking) * scale;
    });
    ctx.restore();
    return width;
  }
  function linear(ctx, x, y, w, h, stops) {
    const g = ctx.createLinearGradient(x, y, x + w, y + h);
    stops.forEach(stop => g.addColorStop(stop[0], stop[1]));
    return g;
  }
  function materialCell(ctx, x, y, w, h, parity) {
    const fill = linear(ctx, x, y, w, h, [[0, parity ? '#254872' : '#2b507d'], [0.55, '#1a3557'], [1, '#152c49']]);
    const cut = Math.min(w, h) * 0.12;
    polygon(ctx, [[x + cut, y], [x + w - cut, y], [x + w, y + cut],
      [x + w, y + h - cut], [x + w - cut, y + h], [x + cut, y + h],
      [x, y + h - cut], [x, y + cut]], fill, '#44617f', 0.65);
    for (let i = 1; i < 5; i++) {
      const fy = y + h * i / 5;
      line(ctx, [[x + cut + 1, fy], [x + w - cut - 1, fy]], '#4c6680', 0.45);
    }
    for (let i = 1; i <= 2; i++) {
      const bx = x + w * i / 3;
      line(ctx, [[bx, y + 2], [bx, y + h - 2]], '#a6b6c5', 0.8);
    }
  }
  function stage(ctx, width, height, minSide) {
    ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'rgba(0,0,0,0)';
    if ('filter' in ctx) ctx.filter = 'none';
    ctx.setLineDash([]); ctx.lineDashOffset = 0;
    ctx.fillStyle = '#0a0d14'; ctx.fillRect(0, 0, width, height);
    const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
    ctx.translate((width - 1920 * scale) * 0.5, (height - 1080 * scale) * 0.5);
    ctx.scale(scale, scale); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    ctx.fillStyle = linear(ctx, 0, 0, 1920, 1080, [[0, '#0c111a'], [0.55, '#0a0d14'], [1, '#090c12']]);
    ctx.fillRect(0, 0, 1920, 1080);
    line(ctx, [[120, 242], [1800, 242]], '#242e3b', 1);
    line(ctx, [[120, 928], [1800, 928]], '#242e3b', 1);
  }
  return { TAU, fract, clamp, lerp, smooth, easeInOutSine, mix, rgba, polygon, roundedPath, box,
    line, circle, text, spaced, spacedWidth, linear, materialCell, stage };
})();

const SolarFloating = (() => {
  const K = SolarKit;
  const TAU = K.TAU;
  const DURATION = 25;

  /* ---------- one shared oblique projection (u = along the field, v = across, z = up) ---------- */
  const OX = 120, OY = 474, AX = 0.97, AY = -0.16, BX = 0.56, BY = 0.68;
  const proj = (u, v, z = 0) => [OX + AX * u + BX * v, OY + AY * u + BY * v - z];
  const metric = (du, dv) => Math.hypot(AX * du + BX * dv, AY * du + BY * dv);
  const SLOPE = Math.atan2(AY, AX);

  /* ---------- layout (world units; everything is symmetric about AXIS) ---------- */
  const WATER = {w: 1000, h: 570, lip: 6};
  const DECK = {x: -12, y: -12, w: 342, h: 214, rise: 8};
  const MODULE = {w: 148, h: 84, dx: 170, dy: 106};
  const ARRAYS = [{u: 52, v: 44}, {u: 534, v: 44}, {u: 293, v: 336}];
  const AXIS = 285;
  const TRUNK = {u0: 197, u1: 878, half: 7};
  const GANGWAY = {u0: 878, u1: 1026, half: 7, rise0: 8, rise1: 13, thick: 3};
  const LAND = {u0: 1000, u1: 1280, top: 10, base: -6};
  const PAD = {u0: 1000, u1: 1050, half: 22, top: 13};
  const DUCT = {u0: 1050, u1: 1090, half: 6};
  const BUILDING = {u0: 1090, u1: 1240, v0: 220, v1: 350, h: 110};
  const MOORINGS = [
    {anchor: [14, 14], attach: [40, 32]},
    {anchor: [890, 14], attach: [864, 32]},
    {anchor: [255, 556], attach: [281, 538]},
    {anchor: [649, 556], attach: [623, 538]}
  ];
  const deckU = i => ARRAYS[i].u + DECK.x + DECK.w / 2;

  /* ---------- palettes ---------- */
  const DECK_STYLE = {top: '#708794', front: '#374f60', left: '#2b4559', stroke: '#9fb3c0'};
  const WALK_STYLE = {top: '#647e8f', front: '#2d4659', left: '#243b4c', stroke: '#a7bac7'};
  const AMBER = '#d8bf8f', BLUE = '#a9c4d6', TEAL = '#8fcab9';

  /* ---------- motion helpers (all integer cycles per loop) ---------- */
  const heave = progress => {
    const p = TAU * progress;
    return 1.8 * Math.sin(2 * p) + 0.4 * Math.sin(3 * p + 0.9);
  };
  const gangLift = (u, lift) => {
    if (u <= GANGWAY.u0) return lift;
    if (u >= GANGWAY.u1) return 0;
    return lift * (GANGWAY.u1 - u) / (GANGWAY.u1 - GANGWAY.u0);
  };
  const plankTop = (u, lift) => K.lerp(GANGWAY.rise0, GANGWAY.rise1,
    K.clamp((u - GANGWAY.u0) / (GANGWAY.u1 - GANGWAY.u0))) + gangLift(u, lift);
  const cableZ = (u, lift) => u <= GANGWAY.u0 ? DECK.rise + lift + 0.4 :
    u < GANGWAY.u1 ? plankTop(u, lift) + 0.4 : PAD.top + 0.4;

  /* ---------- energy routes: world polylines with rounded corners, screen-metric length ---------- */
  function buildRoute(points, radius) {
    const dense = [points[0].slice()];
    const push = p => {
      const q = dense[dense.length - 1].slice();
      const n = Math.max(1, Math.ceil(Math.hypot(p[0] - q[0], p[1] - q[1]) / 6));
      for (let i = 1; i <= n; i++) dense.push([q[0] + (p[0] - q[0]) * i / n, q[1] + (p[1] - q[1]) * i / n]);
    };
    for (let i = 1; i < points.length - 1; i++) {
      const p0 = points[i - 1], p = points[i], p1 = points[i + 1];
      const l0 = Math.hypot(p[0] - p0[0], p[1] - p0[1]), l1 = Math.hypot(p1[0] - p[0], p1[1] - p[1]);
      const d = Math.min(radius, l0 * 0.45, l1 * 0.45);
      const a = [p[0] + (p0[0] - p[0]) * d / l0, p[1] + (p0[1] - p[1]) * d / l0];
      const b = [p[0] + (p1[0] - p[0]) * d / l1, p[1] + (p1[1] - p[1]) * d / l1];
      push(a);
      for (let j = 1; j <= 12; j++) {
        const t = j / 12, s = 1 - t;
        push([s * s * a[0] + 2 * s * t * p[0] + t * t * b[0], s * s * a[1] + 2 * s * t * p[1] + t * t * b[1]]);
      }
    }
    push(points[points.length - 1]);
    const cum = [0];
    for (let i = 1; i < dense.length; i++) {
      cum.push(cum[i - 1] + metric(dense[i][0] - dense[i - 1][0], dense[i][1] - dense[i - 1][1]));
    }
    return {pts: dense, cum, length: cum[cum.length - 1]};
  }
  function sampleRoute(route, d) {
    const c = route.cum;
    d = K.clamp(d, 0, route.length);
    let lo = 0, hi = c.length - 1;
    while (hi - lo > 1) { const m = (lo + hi) >> 1; if (c[m] < d) lo = m; else hi = m; }
    const seg = c[hi] - c[lo] || 1, t = (d - c[lo]) / seg;
    const a = route.pts[lo], b = route.pts[hi];
    return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
  }

  // One constant packet speed for the whole system; whole spacings per loop => seamless.
  const SPACING = 64, PACKETS_PER_LOOP = 25, SPEED = SPACING * PACKETS_PER_LOOP / DURATION;
  const deckFront = ARRAYS[0].v + DECK.y + DECK.h, deckBack = ARRAYS[2].v + DECK.y;
  const STREAMS = [
    {points: [[deckU(0), deckFront + 2], [deckU(0), AXIS], [DUCT.u1, AXIS]], slot: 0},
    {points: [[deckU(2), deckBack + 2], [deckU(2), AXIS], [DUCT.u1, AXIS]], slot: 1},
    {points: [[deckU(1), deckFront + 2], [deckU(1), AXIS], [DUCT.u1, AXIS]], slot: 2}
  ].map(s => {
    const route = buildRoute(s.points, 10);
    const count = Math.ceil(route.length / SPACING) + 1;
    // Phase is measured from the shared end of the trunk so merged streams interleave evenly.
    const phase = ((route.length - s.slot * SPACING / 3) % SPACING + SPACING) % SPACING;
    return {route, count, period: count * SPACING, phase};
  });

  /* ---------- solids ---------- */
  function prism(ctx, u0, v0, u1, v1, z0, z1, c) {
    K.polygon(ctx, [proj(u0, v1, z1), proj(u1, v1, z1), proj(u1, v1, z0), proj(u0, v1, z0)], c.front, c.stroke, 1);
    K.polygon(ctx, [proj(u0, v0, z1), proj(u0, v1, z1), proj(u0, v1, z0), proj(u0, v0, z0)], c.left, c.stroke, 1);
    K.polygon(ctx, [proj(u0, v0, z1), proj(u1, v0, z1), proj(u1, v1, z1), proj(u0, v1, z1)], c.top, c.stroke, 1);
  }
  function hullShadow(ctx, u0, v0, u1, v1, grow) {
    K.polygon(ctx, [proj(u0 - grow, v0 - grow), proj(u1 + grow, v0 - grow),
      proj(u1 + grow, v1 + grow), proj(u0 - grow, v1 + grow)], 'rgba(2,8,13,0.42)', 'rgba(176,204,220,0.20)', 1);
  }
  function along(ctx, x, y, fn) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(SLOPE); fn(); ctx.restore();
  }

  /* ---------- water ---------- */
  function drawWater(ctx, progress) {
    const W = WATER.w, H = WATER.h, lip = WATER.lip;
    const a = proj(0, 0), b = proj(W, 0), c = proj(W, H), d = proj(0, H);
    K.polygon(ctx, [d, c, [c[0], c[1] + lip], [d[0], d[1] + lip]], '#0a1621', '#35495a', 1);
    K.polygon(ctx, [a, d, [d[0], d[1] + lip], [a[0], a[1] + lip]], '#0b1824', '#35495a', 1);
    K.polygon(ctx, [a, b, c, d], K.linear(ctx, a[0], a[1], c[0] - a[0], c[1] - a[1],
      [[0, '#101e2c'], [0.5, '#172d3b'], [1, '#0d1d2a']]), '#496479', 1.2);
    ctx.save();
    K.polygon(ctx, [a, b, c, d]); ctx.clip();
    const rows = 9, pad = 30, samples = 96;
    for (let row = 0; row < rows; row++) {
      const v = 44 + row * (H - 88) / (rows - 1);
      const pts = [];
      for (let i = 0; i <= samples; i++) {
        const k = i / samples;
        const wave = Math.sin(TAU * (2 * k - 2 * progress + row * 0.11));
        pts.push(proj(pad + k * (W - 2 * pad), v + 2.2 * wave));
      }
      const col = row % 2 ? '#6f90a4' : '#4f758b';
      const g = ctx.createLinearGradient(pts[0][0], pts[0][1], pts[samples][0], pts[samples][1]);
      g.addColorStop(0, K.rgba(col, 0)); g.addColorStop(0.15, K.rgba(col, 0.3));
      g.addColorStop(0.85, K.rgba(col, 0.3)); g.addColorStop(1, K.rgba(col, 0));
      K.line(ctx, pts, g, 1.2);
    }
    ctx.restore();
  }

  function drawMoorings(ctx, lift) {
    MOORINGS.forEach(m => {
      const a = proj(m.anchor[0], m.anchor[1], 0), b = proj(m.attach[0], m.attach[1], lift + DECK.rise);
      const len = Math.hypot(b[0] - a[0], b[1] - a[1]);
      ctx.beginPath(); ctx.moveTo(a[0], a[1]);
      ctx.quadraticCurveTo((a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5 + 3 + len * 0.045, b[0], b[1]);
      ctx.strokeStyle = '#5b7385'; ctx.lineWidth = 1.2; ctx.stroke();
      K.circle(ctx, a[0], a[1], 5.2, '#597282', '#9cafbb', 1);
      K.circle(ctx, a[0], a[1], 1.9, '#213947');
    });
  }
  function drawCleats(ctx, lift) {
    MOORINGS.forEach(m => {
      const p = proj(m.attach[0], m.attach[1], lift + DECK.rise);
      K.circle(ctx, p[0], p[1], 2.4, '#d0d9df', '#6d8495', 1);
    });
  }

  /* ---------- shore ---------- */
  function drawLand(ctx) {
    const {u0, u1, top, base} = LAND, H = WATER.h;
    K.polygon(ctx, [proj(u0, H, top), proj(u1, H, top), proj(u1, H, base), proj(u0, H, base)], '#243c50', '#6a869b', 1);
    K.polygon(ctx, [proj(u0, 0, top), proj(u0, H, top), proj(u0, H, 0), proj(u0, 0, 0)], '#2d485d', '#6a869b', 1);
    const tp = [proj(u0, 0, top), proj(u1, 0, top), proj(u1, H, top), proj(u0, H, top)];
    K.polygon(ctx, tp, K.linear(ctx, tp[0][0], tp[0][1], tp[2][0] - tp[0][0], tp[2][1] - tp[0][1],
      [[0, '#1d3042'], [1, '#162636']]), '#587489', 1.1);
    const faint = 'rgba(143,176,196,0.10)';
    for (let k = 1; k < 10; k++) K.line(ctx, [proj(u0, k * 57, top), proj(u1, k * 57, top)], faint, 1);
    for (let u = u0 + 70; u < u1; u += 70) K.line(ctx, [proj(u, 0, top), proj(u, H, top)], faint, 1);
    K.line(ctx, [proj(u0, 0, top), proj(u0, H, top)], '#8aa5b8', 1.4);
  }
  function drawShoreWorks(ctx) {
    prism(ctx, PAD.u0, AXIS - PAD.half, PAD.u1, AXIS + PAD.half, LAND.top, PAD.top,
      {top: '#5a7488', front: '#2d475c', left: '#263f52', stroke: '#9db4c4'});
    prism(ctx, DUCT.u0, AXIS - DUCT.half, DUCT.u1, AXIS + DUCT.half, LAND.top, PAD.top,
      {top: '#46627a', front: '#273f53', left: '#223a4b', stroke: '#86a0b3'});
  }
  function drawBuilding(ctx, progress) {
    const b = BUILDING, z0 = LAND.top, z1 = z0 + b.h;
    prism(ctx, b.u0, b.v0, b.u1, b.v1, z0, z1, {top: '#7d94a7', front: '#4b687e', left: '#3a5368', stroke: '#aec0cf'});
    prism(ctx, b.u0 - 6, b.v0 - 6, b.u1 + 6, b.v1 + 6, z1, z1 + 6,
      {top: '#8ea5b7', front: '#5a778c', left: '#45607a', stroke: '#c0cfda'});
    const pulse = 0.5 + 0.5 * Math.sin(TAU * 5 * progress);
    // front facade (u along x, height along y)
    let o = proj(b.u0, b.v1, z1);
    ctx.save(); ctx.transform(AX, AY, 0, 1, o[0], o[1]);
    K.box(ctx, 14, 40, 40, 70, '#1e3b51', '#91adbf', 2, 1.1);
    K.line(ctx, [[45, 70], [45, 86]], '#b3c5d2', 2);
    K.box(ctx, 66, 14, 70, 40, '#142e42', '#93afc2', 4, 1);
    K.text(ctx, 'GRID', 101, 32, 15, '#d1dfe9', 500, 'center', 52);
    K.line(ctx, [[76, 42], [126, 42]], '#93b7b4', 1.8);
    K.circle(ctx, 127, 23, 2.2, K.mix('#3f6d66', '#a8d6bf', pulse));
    for (let i = 0; i < 4; i++) K.line(ctx, [[66, 68 + i * 10], [136, 68 + i * 10]], '#223f55', 3);
    ctx.restore();
    // water-side facade with the cable entry
    o = proj(b.u0, b.v0, z1);
    ctx.save(); ctx.transform(BX, BY, 0, 1, o[0], o[1]);
    K.box(ctx, 53, 90, 24, 20, '#1e3b51', '#91adbf', 2, 1);
    K.line(ctx, [[58, 100], [72, 100]], '#93b7b4', 1.6);
    ctx.restore();
  }

  /* ---------- floating infrastructure ---------- */
  function drawTrunk(ctx, lift) {
