  const risers = [265, 765].map(x => K.route([[x, 501], [x, 565]], 0));
  /* ------------------------------------------------------------------
   * Electric vehicles
   * Each car is described once as a spec in local space: x runs tail -> nose,
   * y = 0 is the axle line and the ground is y = R. The silhouette, wheel
   * arches, glass, doors, lamps and charge port are all derived from that
   * spec, so both bodies share one structure and one set of proportions
   * (about 77 px per metre: 4.7 m long sedan, 4.8 m long SUV, 0.7 m wheels).
   * ------------------------------------------------------------------ */
  const GROUND = 804;
  const CAR_X = [318, 835];

  function carSpec(o) {
    const archR = o.R + 6;
    return Object.assign({
      archR,
      archDx: Math.sqrt(archR * archR - o.floor * o.floor),
      archAngle: Math.asin(o.floor / archR)
    }, o);
  }

  const CARS = {
    sedan: carSpec({
      R: 27, floor: 12, tail: 8, nose: 367, roofY: -85, xr: 80, xf: 295,
      paint: [[0, '#a6bdc6'], [0.45, '#7195a1'], [1, '#466a7d']],
      pillarColor: '#9db6c0',
      // [x, y, corner radius] from the rear bumper, over the roof, to the front bumper
      outline: [[8, 12, 5], [9, -50, 6], [62, -55, 40], [140, -85, 50], [214, -85, 50],
        [272, -52, 40], [352, -38, 14], [367, -24, 10], [364, 12, 6]],
      glass: [[116, -51], [148, -79], [212, -79], [256, -51]],
      pillars: [[[176.5, -79.5], [181.5, -79.5], [183.5, -50.5], [178.5, -50.5]]],
      doors: [[[124, -50], [123, 3]], [[181, -50], [181, 3]], [[251, -50], [248, 3]]],
      handles: [[133, -44], [188, -44]],
      crease: [128, 246, -30],
      mirror: [251, -60, 17, 9],
      headlight: [[336, -35], [349, -34], [359, -27], [360, -23], [349, -29], [336, -30]],
      tailLamp: [[11, -46], [40, -50], [40, -45], [11, -38]],
      intake: [336, -3, 24, 8],
      port: [34, -26],
      rails: null
    }),
    suv: carSpec({
      R: 28, floor: 12, tail: 8, nose: 375, roofY: -99, xr: 80, xf: 300,
      paint: [[0, '#b3c3d0'], [0.45, '#7e98ae'], [1, '#536f87']],
      pillarColor: '#a3b7c7',
      outline: [[8, 12, 5], [8, -62, 10], [46, -99, 30], [226, -99, 30], [288, -60, 36],
        [360, -52, 14], [375, -34, 10], [372, 12, 6]],
      glass: [[30, -58], [58, -93], [224, -93], [272, -58]],
      pillars: [
        [[127.5, -93.5], [132.5, -93.5], [124.5, -57.5], [119.5, -57.5]],
        [[190.5, -93.5], [195.5, -93.5], [197.5, -57.5], [192.5, -57.5]]
      ],
      doors: [[[122, -57], [121, 3]], [[194, -57], [194, 3]], [[261, -57], [258, 3]]],
      handles: [[130, -52], [201, -52]],
      crease: [128, 252, -34],
      mirror: [262, -67, 17, 9],
      headlight: [[342, -49], [356, -48.5], [369, -37], [370, -32.5], [356, -41], [342, -43]],
      tailLamp: [[11, -52], [38, -54], [38, -48], [11, -42]],
      intake: [343, -5, 26, 8],
      port: [34, -31],
      rails: {y: -103.5, x1: 72, x2: 212, posts: [84, 200]}
    })
  };

  // Absolute position of each car's charge port; the charge cables end here.
  const portAt = (x, car) => [x + car.port[0], GROUND - car.R + car.port[1]];
  const PORTS = [portAt(CAR_X[0], CARS.sedan), portAt(CAR_X[1], CARS.suv)];
  const chargeCables = [
    K.route([[300, 620], [310, 620], [310, PORTS[0][1]], PORTS[0]], 11),
    K.route([[800, 620], [817, 620], [817, PORTS[1][1]], PORTS[1]], 12)
  ];

  function canopy(ctx, progress) {
    K.polygon(ctx, [[130, 806], [1330, 806], [1360, 790], [160, 790]], '#203347', '#536e85', 1);
    K.polygon(ctx, [[130, 806], [1330, 806], [1330, 826], [130, 826]], '#142a3d', '#38556e', 1);
    K.polygon(ctx, [[1330, 806], [1360, 790], [1360, 810], [1330, 826]], '#102538', '#36536c', 1);
    [202, 1265].forEach(x => {
      K.box(ctx, x - 11, 472, 22, 322, K.linear(ctx, x - 11, 472, 22, 322,
        [[0, '#96aebf'], [0.45, '#526f87'], [1, '#344e66']]), '#b0c2d0', 2, 1);
      K.box(ctx, x - 29, 791, 58, 10, '#58738a', '#a2b7c7', 2, 1);
    });
    [293, 689, 810, 1212].forEach(x => K.line(ctx, [[x, 794], [x + 4, 811]], '#a99570', 2));
    const p = [roofPoint(0, 0), roofPoint(1110, 0), roofPoint(1110, 150), roofPoint(0, 150)];
    K.polygon(ctx, [p[0], p[1], [p[1][0], p[1][1] + 18], [p[0][0], p[0][1] + 18]], '#345167', '#8ba3b6', 1.1);
    K.polygon(ctx, [p[1], p[2], [p[2][0], p[2][1] + 14], [p[1][0], p[1][1] + 18]], '#243f56', '#69869e', 1);
    K.polygon(ctx, p, '#344e65', '#8da5b8', 1.2);
    ctx.save(); ctx.transform(1, 0, 0.52, -0.83, 180, 460);
    for (let index = 0; index < 4; index++) {
      const x = 40 + index * 266, y = 18, w = 228, h = 112;
      K.box(ctx, x, y, w, h, K.linear(ctx, x, y, w, h,
        [[0, '#94aabc'], [0.3, '#4d667e'], [1, '#8098ac']]), '#b4c6d3', 2, 1.1);
      K.box(ctx, x + 5, y + 5, w - 10, h - 10, '#102131', null, 1);
      const columns = 6, rows = 3, gap = 3, pad = 10;
      const cw = (w - pad * 2 - (columns - 1) * gap) / columns;
      const ch = (h - pad * 2 - (rows - 1) * gap) / rows;
      for (let r = 0; r < rows; r++) for (let c = 0; c < columns; c++) {
        K.materialCell(ctx, x + pad + c * (cw + gap), y + pad + r * (ch + gap), cw, ch, index + r + c);
      }
      ctx.save(); K.roundedPath(ctx, x + 6, y + 6, w - 12, h - 12, 1); ctx.clip();
      K.reflection(ctx, x + 6, y + 6, w - 12, h - 12, progress, index * 0.10, 0.08);
      ctx.restore();
      K.line(ctx, [[x + w * 0.5, 18], [x + w * 0.5, 12]], '#b0c3d0', 1.3);
    }
    ctx.restore();
    K.line(ctx, roofRail.points, '#8ba5b9', 1.3);
    K.packets(ctx, roofRail, progress, 5, 4, '#d2be99', 0.1, 10, 2.2);
  }

  function wheel(ctx, x, y, r) {
    K.circle(ctx, x, y, r, '#16283a', '#4d687e', 1.2);          // tyre
    K.circle(ctx, x, y, r * 0.8, null, '#2a4156', 1);            // sidewall
    K.circle(ctx, x, y, r * 0.64, '#8aa1b3', '#bed0dd', 1);      // rim
    K.circle(ctx, x, y, r * 0.5, '#2c475c');                     // dish between spokes
    for (let i = 0; i < 5; i++) {
      const angle = -Math.PI * 0.5 + i * K.TAU / 5;
      K.line(ctx, [[x + Math.cos(angle) * r * 0.14, y + Math.sin(angle) * r * 0.14],
        [x + Math.cos(angle) * r * 0.54, y + Math.sin(angle) * r * 0.54]], '#b3c6d4', r * 0.11);
    }
    K.circle(ctx, x, y, r * 0.17, '#d3dfe7', '#607c91', 0.9);    // hub cap
  }

  function pathOf(ctx, points) {
    ctx.beginPath();
    points.forEach((p, i) => { if (i) ctx.lineTo(p[0], p[1]); else ctx.moveTo(p[0], p[1]); });
    ctx.closePath();
  }

  // Full body silhouette: rounded top outline plus the two wheel-arch cut-outs.
  function bodyPath(ctx, c) {
    const o = c.outline, last = o[o.length - 1];
    ctx.beginPath();
    ctx.moveTo(o[0][0] + 12, c.floor);
    for (let i = 0; i < o.length - 1; i++) ctx.arcTo(o[i][0], o[i][1], o[i + 1][0], o[i + 1][1], o[i][2]);
    ctx.arcTo(last[0], last[1], c.xf + c.archDx, c.floor, last[2]);
    ctx.lineTo(c.xf + c.archDx, c.floor);
    ctx.arc(c.xf, 0, c.archR, c.archAngle, Math.PI - c.archAngle, true);
    ctx.lineTo(c.xr + c.archDx, c.floor);
    ctx.arc(c.xr, 0, c.archR, c.archAngle, Math.PI - c.archAngle, true);
    ctx.closePath();
  }

  function carShadow(ctx, c) {
    const span = c.nose - c.tail;
    K.box(ctx, c.tail - 6, c.R - 6.5, span + 12, 7.5, 'rgba(5,9,15,0.34)', null, 3.5);
    K.box(ctx, c.tail + 14, c.R - 4.5, span - 28, 5, 'rgba(4,7,12,0.42)', null, 2.5);
  }

  // Dark cavity behind each tyre, limited to the part that sits inside the body.
  function wheelWells(ctx, c) {
    [c.xr, c.xf].forEach(ax => {
      ctx.save();
      ctx.beginPath();
      ctx.rect(ax - c.archR - 2, -c.archR - 2, c.archR * 2 + 4, c.floor + c.archR + 2);
      ctx.clip();
      K.circle(ctx, ax, 0, c.archR, '#08121b');
      ctx.restore();
    });
  }

  function greenhouse(ctx, c) {
    const g = c.glass;
    K.polygon(ctx, g, '#19374d', '#bdd0dd', 1);
    const xs = g.map(p => p[0]), ys = g.map(p => p[1]);
    const x0 = Math.min.apply(null, xs), w = Math.max.apply(null, xs) - x0;
    const y0 = Math.min.apply(null, ys), h = Math.max.apply(null, ys) - y0;
    ctx.save();
    pathOf(ctx, g); ctx.clip();
    [[0.34, 0.11, 'rgba(183,204,224,0.12)'], [0.58, 0.05, 'rgba(183,204,224,0.08)']].forEach(s => {
      const sx = x0 + w * s[0], sw = w * s[1], lean = h * 0.9;
      K.polygon(ctx, [[sx + lean, y0], [sx + lean + sw, y0], [sx + sw, y0 + h], [sx, y0 + h]], s[2]);
    });
    ctx.restore();
    c.pillars.forEach(p => K.polygon(ctx, p, c.pillarColor));
    K.line(ctx, [g[0], g[3]], '#a9bfcd', 1.6);                   // belt-line trim
  }

  function carDetails(ctx, c) {
    const sillFrom = c.xr + c.archDx + 3, sillTo = c.xf - c.archDx - 3;
    K.line(ctx, [[c.crease[0], c.crease[2]], [c.crease[1], c.crease[2]]], 'rgba(205,220,232,0.30)', 1.2);
    K.line(ctx, [[sillFrom, 3], [sillTo, 3]], '#35536b', 1);
    c.doors.forEach(d => K.line(ctx, d, '#3d5c74', 1));
    c.handles.forEach(h => K.box(ctx, h[0], h[1], 15, 3.6, '#cbd9e3', '#7f98ab', 1.6, 0.6));
    const m = c.mirror;
    K.box(ctx, m[0], m[1], m[2], m[3], '#97aebf', '#c4d3de', 3.5, 0.9);
    K.polygon(ctx, c.headlight, '#dddfce', '#eef0e7', 0.8);
    K.polygon(ctx, c.tailLamp, '#b58f82', '#d2afa2', 0.8);
    K.box(ctx, c.intake[0], c.intake[1], c.intake[2], c.intake[3], '#1b3042', '#3d5a72', 3, 0.8);
    if (c.rails) {
      const r = c.rails;
      r.posts.forEach(px => K.line(ctx, [[px, r.y], [px, r.y + 4.5]], '#7b94a8', 2));
      K.line(ctx, [[r.x1, r.y], [r.x2, r.y]], '#8097ab', 2.6);
    }
    const px = c.port[0], py = c.port[1];                         // charge-port flap and socket
    K.box(ctx, px - 8, py - 7, 16, 14, '#6f8aa0', '#aebfcc', 4, 0.9);
    K.circle(ctx, px, py, 6, '#10202e', '#8facbf', 0.8);
  }

  function vehicle(ctx, x, suv) {
    const c = suv ? CARS.suv : CARS.sedan;
    ctx.save(); ctx.translate(x, GROUND - c.R);
    carShadow(ctx, c);
    wheelWells(ctx, c);
    bodyPath(ctx, c);
    ctx.fillStyle = K.linear(ctx, c.tail, c.roofY, c.nose - c.tail, c.floor - c.roofY, c.paint);
    ctx.fill();
    ctx.save(); bodyPath(ctx, c); ctx.clip();                     // darker lower body
    const shade = ctx.createLinearGradient(0, -34, 0, c.floor);
    shade.addColorStop(0, 'rgba(14,34,50,0)'); shade.addColorStop(1, 'rgba(14,34,50,0.42)');
    ctx.fillStyle = shade; ctx.fillRect(c.tail - 4, -34, c.nose - c.tail + 8, c.floor + 36);
    ctx.restore();
    bodyPath(ctx, c);
    ctx.strokeStyle = '#c3d0da'; ctx.lineWidth = 1.2; ctx.stroke();
    greenhouse(ctx, c);
    carDetails(ctx, c);
    wheel(ctx, c.xr, 0, c.R); wheel(ctx, c.xf, 0, c.R);
    ctx.restore();
  }

  function charger(ctx, x, index, phase) {
    const y = 565;
    K.box(ctx, x + 4, y + 5, 70, 208, '#1c3347', '#3b5870', 7, 1);
    K.box(ctx, x, y, 70, 208, '#59778e', '#acc0cf', 7, 1.2);
    K.box(ctx, x + 11, y + 18, 48, 52, '#142e42', '#8facbf', 4, 1);
    K.box(ctx, x + 19, y + 31, 29, 23, '#2a495f', '#96afbf', 2, 1);
    K.box(ctx, x + 48, y + 38, 3, 9, '#96afbf', null, 1);
    const reserve = 0.58 + 0.065 * Math.sin(phase - index * 0.7);
    K.box(ctx, x + 23, y + 35, 21 * reserve, 15, '#99c2b5', null, 1);
    K.text(ctx, String.fromCharCode(65 + index), x + 35, y + 105, 22, '#d6e4ed', 500, 'center', 50);
    for (let i = 0; i < 4; i++) K.line(ctx, [[x + 18, y + 141 + i * 9], [x + 52, y + 141 + i * 9]], '#29475f', 2.5);
    K.box(ctx, x - 8, y + 208, 86, 12, '#2a455d', '#7695ad', 2, 1);
    K.circle(ctx, x + 35, y, 4, '#2d4b62', '#b5cad8', 1);
    K.circle(ctx, x + 70, 620, 4.5, '#203b50', '#bdd0dd', 1.1);
  }

  function powerControl(ctx, phase) {
    const x = 1450, y = 414, w = 330, h = 378;
    K.box(ctx, x + 5, y + 7, w, h, '#1a3043', '#39556b', 12, 1);
    K.box(ctx, x, y, w, h, K.linear(ctx, x, y, w, h,
      [[0, '#627e94'], [0.3, '#3a5870'], [1, '#28465d']]), '#a3baca', 12, 1.3);
    K.spaced(ctx, 'POWER CONTROL', x + 28, y + 38, 15, 1.8, '#d5e1e9', w - 56);
    K.box(ctx, x + 26, y + 66, w - 52, 72, '#132b3f', '#7d9db4', 5, 1);
    K.text(ctx, 'DC BUS', x + 46, y + 102, 28, '#d1e0ea', 500, 'left', w - 92);
    K.spaced(ctx, 'SOLAR SUPPLY', x + 46, y + 123, 10, 1.4, '#95b3c8', w - 92);
    [0, 1].forEach(i => {
      const by = y + 177 + i * 95;
      K.box(ctx, x + 26, by, w - 52, 72, '#1b354b', '#5d7f99', 5, 1);
      K.spaced(ctx, 'STALL ' + String.fromCharCode(65 + i), x + 40, by + 23, 10, 1.4, '#b5cad9', 130);
      K.text(ctx, 'CHARGING', x + w - 40, by + 23, 10, '#a2c4b5', 500, 'right', 110);
      K.box(ctx, x + 40, by + 42, w - 80, 9, '#2d4c63', null, 3);
      K.box(ctx, x + 40, by + 42, (w - 80) * (0.60 + 0.055 * Math.sin(phase - i * 0.7)), 9, '#9bc0b7', null, 3);
    });
    [[1450, 452], [1450, 570]].forEach(p => K.circle(ctx, p[0], p[1], 4.5, '#29475f', '#bad0de', 1.1));
    K.spaced(ctx, 'SOLAR POWER CONTROL', 1450, 870, 13, 1.8, '#95acc0', 350);
  }

  function paint(ctx, progress, phase) {
    K.spaced(ctx, 'SOLAR ELECTRIC MOBILITY', 120, 98, 16, 2.8, '#94a6bb', 950);
    K.text(ctx, 'Solar charging pavilion', 116, 172, 66, '#e4ebf2', 500, 'left', 1300);
    K.text(ctx, 'Solar collection. Connected charging.', 120, 211, 21, '#8fa1b4', 400, 'left', 1200);
    K.box(ctx, 1512, 100, 288, 51, '#131c27', '#334252', 25, 1);
    K.circle(ctx, 1540, 125, 4, '#9abcad');
    K.spaced(ctx, 'CHARGING ONLINE', 1558, 131, 12.5, 1.8, '#c2cfd9', 221);
    canopy(ctx, progress);
    [[input, '#d1bc94', 6, 3], [service, '#a6c9c4', 6, 6]].forEach((entry, i) => {
      K.line(ctx, entry[0].points, '#172f43', 7);
      K.line(ctx, entry[0].points, '#7896ad', 1.8);
      K.packets(ctx, entry[0], progress, entry[2], entry[3], entry[1], 0.1 + i * 0.12, 10, 2.8);
    });
    risers.forEach((path, i) => {
      K.line(ctx, path.points, '#7896ad', 1.5);
      K.packets(ctx, path, progress, 5, 2, '#aacbc6', i * 0.16, 7, 2.4);
      K.circle(ctx, path.points[0][0], 501, 3, '#aac2d1');
    });
    vehicle(ctx, CAR_X[0], false); vehicle(ctx, CAR_X[1], true);
    charger(ctx, 230, 0, phase); charger(ctx, 730, 1, phase);
    chargeCables.forEach((path, i) => {
      K.line(ctx, path.points, '#132d41', 7);
      K.line(ctx, path.points, '#95adbd', 3.1);
      K.packets(ctx, path, progress, 5, 2, '#c2d8d0', i * 0.11, 7, 2.3);
    });
    PORTS.forEach(p => {
      K.circle(ctx, p[0], p[1], 5.2, '#1e394d', '#d1e0e9', 1.2);
      K.circle(ctx, p[0], p[1], 1.7, '#b6cfd9');
    });
    powerControl(ctx, phase);
    K.spaced(ctx, 'STALL A / CONNECTED', 318, 870, 13, 1.8, '#95acc0', 360);
    K.spaced(ctx, 'STALL B / CONNECTED', 835, 870, 13, 1.8, '#95acc0', 360);
    const footer = [[120, '#d0b78d', 'SOLAR GENERATION'], [585, '#9bb8ce', 'ELECTRIC MOBILITY'], [1100, '#8bb8af', 'COORDINATED CHARGING']];
    footer.forEach(item => {
      K.box(ctx, item[0], 971, 13, 13, item[1], null, 2);
      K.spaced(ctx, item[2], item[0] + 27, 983, 13, 2.0, '#9caec1', 375);
    });
    K.text(ctx, 'SOLAR / ELECTRIC CHARGING', 1800, 983, 14, '#8fa2b5', 400, 'right', 350);
  }
  return {paint};
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const progress = (currentScene + sceneProgress) / sceneCount;
  const phase = SolarKit.TAU * progress;
  ctx.save();
  try {
    SolarKit.stage(ctx, width, height, minSide);
    SolarCharging.paint(ctx, progress, phase);
  } finally {
    ctx.restore();
  }
}

draw.meta = meta;
const animation = Object.freeze({meta, render: draw});

/*
 * Concept 10: Solar Powered Industry - Rooftop Microgrid
 * Duration: 25 seconds
 * Resolution: 3840 x 2160
 * Frame rate: 60 fps
 * One continuous scene; deterministic seamless loop; time is in seconds.
 * Canvas 2D only. No assets, imports, DOM, glow, bloom, or blur.
 * Export target: 100 Mbps (100000000 bits per second).
