      const a = [p[0] + (prev[0] - p[0]) * d / da, p[1] + (prev[1] - p[1]) * d / da];
      const b = [p[0] + (next[0] - p[0]) * d / db, p[1] + (next[1] - p[1]) * d / db];
      result.push(a);
      for (let j = 1; j <= 32; j++) {
        const u = j / 32, v = 1 - u;
        result.push([v * v * a[0] + 2 * v * u * p[0] + u * u * b[0],
          v * v * a[1] + 2 * v * u * p[1] + u * u * b[1]]);
      }
    }
    result.push(points[points.length - 1].slice());
    const lengths = [0];
    for (let i = 1; i < result.length; i++) {
      lengths.push(lengths[i - 1] + Math.hypot(result[i][0] - result[i - 1][0], result[i][1] - result[i - 1][1]));
    }
    return { points: result, lengths, length: lengths[lengths.length - 1] };
