/*
 * Concept 01: Solar Harvest - Premium Panel Array (revised)
 * Duration: 25 seconds
 * Resolution: 3840 x 2160
 * Frame rate: 60 fps
 * One continuous scene; deterministic seamless loop; time is in seconds.
 * Canvas 2D only. No assets, imports, DOM, glow, bloom, or blur.
 * Export target: 100 Mbps (100000000 bits per second).
 * The host encoder must enforce the bitrate; Canvas itself draws frames only.
 *
 * Motion system (every motion is locked to the 25 s loop):
 *   - Energy and light packets travel at one constant speed per layer. Their
 *     spacing is uniform, so density and velocity look identical on every path.
 *   - Packets fade in and out with smoothstep; nothing appears or vanishes abruptly.
 *   - The glass glint is ONE coordinated sweep across the whole array with
 *     sine ease-in / ease-out and a smooth alpha envelope.
 *   - Sun rays rotate at constant angular speed; their breathing is synchronous.
 *   - The waveform translates rigidly (shape never morphs).
 *   - Status lights pulse in an evenly staggered cascade.
 *
 * Geometry rules:
 *   - Panels are drawn as projected polygons, never through a skewed canvas
 *     transform, so strokes, circles and cells keep their true proportions.
 *   - The layout is solved from a few constants (margins, centre line, grid).
 */
'use strict';

const meta = Object.freeze({
  id: 'solar_harvest',
  title: 'Solar Harvest - Premium Panel Array',
  width: 3840,
  height: 2160,
  fps: 60,
  duration: 25,
  sceneCount: 1,
  targetVideoBitrate: 100000000,
  background: '#0a0d14'
