const SolarKit = (() => {
  const TAU = Math.PI * 2;
  const fract = n => n - Math.floor(n);
  const clamp = (n, a = 0, b = 1) => Math.max(a, Math.min(b, n));
  function smooth(a, b, n) {
    const u = clamp((n - a) / (b - a));
    return u * u * (3 - 2 * u);
  }
  function polygon(ctx, points, fill, stroke, lineWidth = 1) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth; ctx.stroke(); }
  }
  function roundedPath(ctx, x, y, w, h, radius = 10) {
    const r = Math.min(radius, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function box(ctx, x, y, w, h, fill, stroke, radius = 10, lineWidth = 1) {
    roundedPath(ctx, x, y, w, h, radius);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth; ctx.stroke(); }
  }
  function line(ctx, points, color, width = 1) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.stroke();
  }
  function circle(ctx, x, y, r, fill, stroke, lineWidth = 1) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth; ctx.stroke(); }
  }
  function text(ctx, value, x, y, size, color, weight = 400, align = 'left', maxWidth = Infinity) {
    ctx.save();
    let fitted = size;
    ctx.font = weight + ' ' + fitted + 'px Arial, "DejaVu Sans", Helvetica, sans-serif';
    const measured = ctx.measureText(value).width;
    if (measured > maxWidth) {
      fitted *= maxWidth / measured;
      ctx.font = weight + ' ' + fitted + 'px Arial, "DejaVu Sans", Helvetica, sans-serif';
    }
    ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color; ctx.fillText(value, x, y);
    ctx.restore();
  }
  function spaced(ctx, value, x, y, size, tracking, color, maxWidth = Infinity) {
    ctx.save();
    ctx.font = '600 ' + size + 'px Arial, "DejaVu Sans", Helvetica, sans-serif';
    const letters = Array.from(value);
    const widths = letters.map(c => ctx.measureText(c).width);
    const total = widths.reduce((a, b) => a + b, 0) + tracking * Math.max(0, letters.length - 1);
    const scale = Math.min(1, maxWidth / total);
    ctx.font = '600 ' + size * scale + 'px Arial, "DejaVu Sans", Helvetica, sans-serif';
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = color;
    let cursor = x;
    letters.forEach((letter, i) => {
      ctx.fillText(letter, cursor, y);
      cursor += (widths[i] + tracking) * scale;
    });
    ctx.restore();
  }
  function linear(ctx, x, y, w, h, stops) {
    const g = ctx.createLinearGradient(x, y, x + w, y + h);
    stops.forEach(stop => g.addColorStop(stop[0], stop[1]));
    return g;
  }
  function route(points, radius = 18) {
    const result = [points[0].slice()];
    for (let i = 1; i < points.length - 1; i++) {
      const prev = points[i - 1], p = points[i], next = points[i + 1];
      const da = Math.hypot(p[0] - prev[0], p[1] - prev[1]);
      const db = Math.hypot(next[0] - p[0], next[1] - p[1]);
      const d = Math.min(radius, da * 0.42, db * 0.42);
      const a = [p[0] + (prev[0] - p[0]) * d / da, p[1] + (prev[1] - p[1]) * d / da];
      const b = [p[0] + (next[0] - p[0]) * d / db, p[1] + (next[1] - p[1]) * d / db];
      result.push(a);
      for (let j = 1; j <= 10; j++) {
        const u = j / 10, v = 1 - u;
        result.push([v * v * a[0] + 2 * v * u * p[0] + u * u * b[0],
          v * v * a[1] + 2 * v * u * p[1] + u * u * b[1]]);
      }
    }
    result.push(points[points.length - 1].slice());
    const lengths = [0];
    for (let i = 1; i < result.length; i++) {
      lengths.push(lengths[i - 1] + Math.hypot(result[i][0] - result[i - 1][0], result[i][1] - result[i - 1][1]));
    }
    return { points: result, lengths, length: lengths[lengths.length - 1] };
  }
  function atPath(path, u) {
    const d = clamp(u) * path.length;
    let i = 1;
    while (i < path.lengths.length - 1 && path.lengths[i] < d) i++;
    const a = path.points[i - 1], b = path.points[i];
    const distance = path.lengths[i] - path.lengths[i - 1];
    const v = distance > 0 ? (d - path.lengths[i - 1]) / distance : 0;
    return {x: a[0] + (b[0] - a[0]) * v, y: a[1] + (b[1] - a[1]) * v,
      angle: Math.atan2(b[1] - a[1], b[0] - a[0])};
  }
  function packets(ctx, path, progress, turns, count, color, offset = 0, size = 12, width = 3) {
    for (let i = 0; i < count; i++) {
      const u = fract(progress * turns + i / count + offset);
      const alpha = smooth(0, 0.075, u) * (1 - smooth(0.925, 1, u));
      if (alpha < 0.002) continue;
      const pose = atPath(path, u);
      ctx.save(); ctx.globalAlpha *= alpha;
      ctx.translate(pose.x, pose.y); ctx.rotate(pose.angle);
      line(ctx, [[-size * 0.5, 0], [size * 0.5, 0]], color, width);
      ctx.restore();
    }
  }
  function materialCell(ctx, x, y, w, h, index, detailed = false) {
    const fill = linear(ctx, x, y, w, h, [[0, index % 2 ? '#254872' : '#2b507d'], [0.55, '#1a3557'], [1, '#152c49']]);
    const cut = Math.min(w, h) * 0.12;
    polygon(ctx, [[x + cut, y], [x + w - cut, y], [x + w, y + cut],
      [x + w, y + h - cut], [x + w - cut, y + h], [x + cut, y + h],
      [x, y + h - cut], [x, y + cut]], fill, '#44617f', detailed ? 1.1 : 0.65);
    const fingers = detailed ? 9 : 5;
    for (let i = 1; i < fingers; i++) {
      const fy = y + h * i / fingers;
      line(ctx, [[x + cut + 1, fy], [x + w - cut - 1, fy]], '#4c6680', detailed ? 0.85 : 0.45);
    }
    const bars = detailed ? 3 : 2;
    for (let i = 1; i <= bars; i++) {
      const bx = x + w * i / (bars + 1);
      line(ctx, [[bx, y + 2], [bx, y + h - 2]], '#a6b6c5', detailed ? 1.75 : 0.8);
    }
  }
  function reflection(ctx, x, y, w, h, progress, offset, strength = 0.16) {
    const u = fract(progress * 2 + offset);
    const alpha = Math.sin(Math.PI * u) ** 2 * strength;
    const cx = x - w * 0.35 + u * w * 1.7;
    ctx.save(); ctx.globalAlpha *= alpha;
    polygon(ctx, [[cx - 42, y], [cx + 24, y], [cx + 118, y + h], [cx + 52, y + h]], '#b7cce0');
    ctx.restore();
  }
  function stage(ctx, width, height, minSide) {
    ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'rgba(0,0,0,0)';
    if ('filter' in ctx) ctx.filter = 'none';
    ctx.setLineDash([]); ctx.lineDashOffset = 0;
    ctx.fillStyle = '#0a0d14'; ctx.fillRect(0, 0, width, height);
    const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
    ctx.translate((width - 1920 * scale) * 0.5, (height - 1080 * scale) * 0.5);
    ctx.scale(scale, scale); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    ctx.fillStyle = linear(ctx, 0, 0, 1920, 1080, [[0, '#0c111a'], [0.55, '#0a0d14'], [1, '#090c12']]);
    ctx.fillRect(0, 0, 1920, 1080);
    line(ctx, [[120, 242], [1800, 242]], '#242e3b', 1);
    line(ctx, [[120, 928], [1800, 928]], '#242e3b', 1);
  }
  return { TAU, fract, clamp, smooth, polygon, roundedPath, box, line, circle,
    text, spaced, linear, route, atPath, packets, materialCell, reflection, stage };
})();

